CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'CUSTOMER');
CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,description VARCHAR(2000),price NUMERIC(12,2) NOT NULL,stock INTEGER NOT NULL DEFAULT 0,image_url VARCHAR(1000));
CREATE TABLE IF NOT EXISTS cart_items (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE,quantity INTEGER NOT NULL CHECK(quantity>0),UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS orders (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),total_amount NUMERIC(12,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL,unit_price NUMERIC(12,2) NOT NULL);
